function editCrosswalk(id){let x=G.taxonomyCrosswalks.find(r=>r.xwId===id);if(!x)return;G.crosswalkBuilder=JSON.parse(JSON.stringify(x));G.crosswalkSuggestions=[];persist(true);go(69)}
