function courseCanonicalPool(){return[...TRAINING_COURSES.map(c=>({...c,id:c.code,titleAr:c.name,titleEn:c.englishName,canonical:true})),...G.createdCourses.map(c=>({...c,code:c.id,name:c.titleAr||c.referenceTopic,englishName:c.titleEn,id:c.id,canonical:true}))]}
function courseTitleAliases(courseId){return G.courseAliases.filter(a=>a.courseId===courseId&&a.status!=='موقوف').map(a=>a.title)}
