function rEnrollment(){let d=data[37];let c=selectedCourse();
  let e=G.enroll=G.enroll||{step:0};
  let steps=['اختيار الطرح','بيانات المشارك','الموافقات','التأكيد'];
  if(e.step>=3)return `<div class="card success"><div class="ck">${IC.check}</div><h2>استُلم طلب تسجيلك 🎉</h2>
    <p>طلب التسجيل في «${esc(c.title)}» بانتظار تأكيد المركز — تابع حالتك من لوحة المتعلم.</p>
    <div style="display:flex;gap:10px;justify-content:center"><button class="btn primary" onclick="G.enroll={step:0};persist(true);go(38)">لوحة المتعلم</button><button class="btn ghost" onclick="G.enroll={step:0};persist(true);go(35)">دورات أخرى</button></div></div>`;
  let body='';
  if(e.step===0)body=`<div class="rolecard sel" style="cursor:default"><b>${esc(c.title)}</b><small>${esc(c.date)} — ${esc(c.place)} · ${esc(c.mode)} · ${esc(c.lang)}</small>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><span class="tagb gold">${esc(c.seats)} متاحًا</span><b style="color:var(--gold-2);font-size:17px">${esc(c.price)}</b></div></div>
    <div class="note mt">آخر موعد للتسجيل: قبل 6 أيام من بدء الدورة — يمكن إلغاء التسجيل مجانًا قبل 72 ساعة.</div>`;
  else if(e.step===1)body=`<div class="fields">
      <div class="field"><label>صفة مقدم الطلب <em>*</em></label><select class="ctl" onchange="G.enroll.who=this.value;persist(true)"><option ${e.who==='المتعلم نفسه'?'selected':''}>المتعلم نفسه</option><option ${e.who==='ممثل جهة يرشح مشاركًا'?'selected':''}>ممثل جهة يرشح مشاركًا</option></select></div>
      <div class="field"><label>الاسم الكامل للمشارك <em>*</em></label><input class="ctl" value="${esc(e.name||W.fullName||'')}" oninput="G.enroll.name=this.value;persist(true)"></div>
      <div class="field"><label>البريد الإلكتروني <em>*</em></label><input class="ctl" type="email" value="${esc(e.email||W.email||'')}" oninput="G.enroll.email=this.value;persist(true)"></div>
      <div class="field"><label>جهة العمل</label><input class="ctl" value="${esc(e.org||'')}" oninput="G.enroll.org=this.value;persist(true)"></div></div>`;
  else body=`<div class="fields" style="grid-template-columns:1fr">
      ${['أقر بصحة البيانات المقدمة','أوافق على سياسة الحضور والإلغاء','أوافق على مشاركة بياناتي مع المركز لغرض التسجيل'].map((t,i)=>`<label class="rolecard" style="display:flex;align-items:center;gap:10px;padding:13px 16px;cursor:pointer"><input type="checkbox" ${(e['c'+i])?'checked':''} onchange="G.enroll.c${i}=this.checked;persist(true)"> <b style="font-size:12.5px">${t}</b></label>`).join('')}
      <div class="field"><label>موافقة جهة العمل (إن وجدت)</label><label class="filebox"><input type="file" style="display:none" onchange="G.enroll.approval=this.files[0]?.name;persist(true);render()"><b>⭱ رفع خطاب الموافقة</b></label>${e.approval?`<span class="filetag">${esc(e.approval)}</span>`:''}</div></div>`;
  return pagehead(d)+`<div class="card formcard" style="min-height:0;max-width:760px">
    <div class="chips" style="margin-bottom:18px">${steps.map((s,i)=>`<span class="chip static ${i===e.step?'sel':''}" style="${i<e.step?'background:var(--green-soft);border-color:#9fd3b8;color:var(--green)':''}">${i<e.step?'✓ ':''}${s}</span>`).join('')}</div>
    ${body}
    <div class="wizfoot"><button class="btn ghost" ${e.step===0?'disabled':''} onclick="G.enroll.step--;persist(true);render()">→ السابق</button><span class="sp"></span>
      <button class="btn primary" onclick="enrollNext()">${e.step===2?'تأكيد وإرسال الطلب ✓':'متابعة ←'}</button></div></div>`}
function enrollNext(){let e=G.enroll;
  if(e.step===1&&(!e.name&&!W.fullName)){toast('أدخل اسم المشارك');return}
  if(e.step===2&&!(e.c0&&e.c1&&e.c2)){toast('الإقرارات الثلاثة مطلوبة');return}
  e.step++;if(e.step>=3){G.enrollments=G.enrollments||[];G.enrollments.push(dec(G.course||'')||selectedCourse().title)}
  persist(true);render();window.scrollTo({top:0})}
