  let centers=[['معهد الريادة للتدريب','الرياض · 24 دورة','4.7',43],['أكاديمية المستقبل','دبي · 18 دورة','4.6',43],['مركز النخبة','مسقط · 12 دورة','4.5',43]];
  let list=kind==='trainer'?trainers:centers;
